function ContactModal({initial,onClose,onSave}:{initial?:Contact;onClose:()=>void;onSave:(c:Contact)=>void}){const [name,setName]=useState(initial?.name||''),[phone,setPhone]=useState(initial?.phone||''),[email,setEmail]=useState(initial?.email||''),[tags,setTags]=useState(initial?.tags.join(', ')||''),[notes,setNotes]=useState(initial?.notes||''),[consent,setConsent]=useState(initial?.consent||false),[consentAt,setConsentAt]=useState(initial?.consentRecordedAt?instantToLocalInput(initial.consentRecordedAt,Intl.DateTimeFormat().resolvedOptions().timeZone):''),[consentSource,setConsentSource]=useState(initial?.consentSource||''),[optedOut,setOptedOut]=useState(initial?.optedOut||false),[error,setError]=useState('');const save=(e:any)=>{e.preventDefault();if(!validPhone(phone))return setError('Use an international phone number like +923001234567.');if(optedOut&&consent)return setError('A contact cannot be both opted out and consented.');if(consent&&!optedOut&&(!consentAt||!consentSource.trim()))return setError('Enter when and how this contact gave consent.');const hasConsent=consent&&!optedOut;onSave({...initial||blankContact(),name:name.trim(),phone:phone.replace(/[\s()-]/g,''),email,tags:tags.split(',').map(x=>x.trim()).filter(Boolean),notes,consent:hasConsent,consentRecordedAt:hasConsent?new Date(consentAt).toISOString():undefined,consentSource:hasConsent?consentSource.trim():undefined,optedOut,optedOutAt:optedOut?(initial?.optedOutAt||new Date().toISOString()):undefined})};return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="modal" onSubmit={save}><div className="modalhead"><div><div className="eyebrow">Contact profile</div><h2>{initial?'Edit contact':'Add contact'}</h2></div><button type="button" className="icon-btn" onClick={onClose}><X size={16}/></button></div><div className="formgrid"><div className="field"><label>Full name</label><input required value={name} onChange={e=>setName(e.target.value)} placeholder="Customer name"/></div><div className="field"><label>WhatsApp phone</label><input required value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+923001234567"/></div><div className="field"><label>Email (optional)</label><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="customer@example.com"/></div><div className="field"><label>Tags (comma separated)</label><input value={tags} onChange={e=>setTags(e.target.value)} placeholder="Appointment, VIP"/></div><div className="field full"><label>Notes</label><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Internal notes"/></div><label className="checkrow field full"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/> This customer has given permission to receive relevant WhatsApp messages.</label>{consent&&!optedOut&&<><div className="field"><label>Consent recorded at</label><input type="datetime-local" required value={consentAt} onChange={e=>setConsentAt(e.target.value)}/></div><div className="field"><label>Consent source</label><input required value={consentSource} onChange={e=>setConsentSource(e.target.value)} placeholder="Website form, signed form, etc."/></div></>}<label className="checkrow field full"><input type="checkbox" checked={optedOut} onChange={e=>setOptedOut(e.target.checked)}/> This contact has opted out and must be suppressed.</label>{error&&<div className="field full" role="alert" style={{color:'#b44949',fontSize:11}}>{error}</div>}</div><div className="modalfoot"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button type="submit" className="primary"><Check size={14}/>Save contact</button></div></form></div>}
function TemplateModal({initial,onClose,onSave}:{initial?:Template;onClose:()=>void;onSave:(t:Template)=>void}){const [name,setName]=useState(initial?.name||''),[category,setCategory]=useState(initial?.category||'Appointment'),[body,setBody]=useState(initial?.body||''),[error,setError]=useState('');return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="modal" onSubmit={e=>{e.preventDefault();if(!body.trim())return setError('Add the template text.');onSave({id:initial?.id||crypto.randomUUID(),name:name.trim(),category,body,approved:initial?.approved||false})}}><div className="modalhead"><div><div className="eyebrow">Reusable message</div><h2>{initial?'Edit template':'New template'}</h2></div><button type="button" className="icon-btn" onClick={onClose}><X size={16}/></button></div><div className="formgrid"><div className="field"><label>Template name</label><input required value={name} onChange={e=>setName(e.target.value)}/></div><div className="field"><label>Category</label><select value={category} onChange={e=>setCategory(e.target.value)}>{['Appointment','Payment','School fee','Invoice','Subscription renewal','Birthday','Event','Follow-up','Custom reminder'].map(x=><option key={x}>{x}</option>)}</select></div><div className="field full"><label>Message text</label><textarea style={{minHeight:120}} value={body} onChange={e=>setBody(e.target.value)} placeholder="Use {{customer_name}}, {{appointment_date}}, {{amount}}, {{business_name}}"/></div><div className="field full"><span className="muted">This saves as a local draft. It does not submit anything to Meta for review or grant approval.</span>{error&&<span style={{color:'#b44949',fontSize:11}}>{error}</span>}</div></div><div className="modalfoot"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary"><Check size={14}/>Save draft</button></div></form></div>}
